import java.nio.file.*;
import java.util.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
public class BicycleK2Probe {
 public static void main(String[]args)throws Exception{
  var type=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimNode");var state=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimState");var variables=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimationVariableSource");var source=Class.forName("zombie.core.skinnedmodel.advancedanimation.IAnimationVariableSource");var set=variables.getMethod("setVariable",String.class,String.class);int checked=0;
  try(var files=Files.walk(Path.of(args[0]))){for(var path:files.filter(p->p.toString().endsWith(".xml")&&p.getFileName().toString().matches("ProjectYakuza_DD_Bicycle(?:Light0[123]|Heavy|Ground|Idle|RelaxedIdle)\\.xml")).toList()){
   var doc=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(path.toFile());Object parsed=type.getMethod("Parse",String.class).invoke(null,path.toAbsolutePath().toString());Object st=state.getConstructor().newInstance(),vars=variables.getConstructor().newInstance();state.getMethod("addNode",type).invoke(st,parsed);var conditions=doc.getElementsByTagName("m_Conditions");
   for(int i=0;i<conditions.getLength();i++){var c=(Element)conditions.item(i);set.invoke(vars,c.getElementsByTagName("m_Name").item(0).getTextContent(),c.getElementsByTagName("m_Value").item(0).getTextContent());}
   var select=state.getMethod("getAnimNodes",source,List.class);if(((List<?>)select.invoke(st,vars,new ArrayList<>())).size()!=1)throw new AssertionError("native bicycle selector "+path);set.invoke(vars,"ProjectYakuzaWeaponProfile","crate");if(!((List<?>)select.invoke(st,vars,new ArrayList<>())).isEmpty())throw new AssertionError("bicycle selector leaked into crate "+path);checked++;
  }}
  var fs=Class.forName("zombie.ZomboidFileSystem");Object folder=fs.getField("base").get(fs.getField("instance").get(null));var game=Path.of("F:/SteamLibrary/steamapps/common/ProjectZomboid").toFile().getCanonicalFile();for(String key:new String[]{"absoluteFile","canonicalFile"})folder.getClass().getField(key).set(folder,game);folder.getClass().getField("canonicalUri").set(folder,game.toURI());folder.getClass().getField("lowercaseUri").set(folder,java.net.URI.create(game.toURI().toString().toLowerCase(java.util.Locale.ROOT)));
  Object movement=state.getConstructor().newInstance();Path nativeMovement=Path.of("F:/SteamLibrary/steamapps/common/ProjectZomboid/media/AnimSets/player/movement");
  try(var files=Files.list(nativeMovement)){for(Path path:files.filter(p->p.toString().endsWith(".xml")).toList())state.getMethod("addNode",type).invoke(movement,type.getMethod("Parse",String.class).invoke(null,path.toString()));}
  Path custom=Path.of(args[0]).resolve("movement/ProjectYakuza_DD_BicycleWalk.xml");Object customNode=type.getMethod("Parse",String.class).invoke(null,custom.toString());state.getMethod("addNode",type).invoke(movement,customNode);Object vars=variables.getConstructor().newInstance();var select=state.getMethod("getAnimNodes",source,List.class);
  for(String[] row:new String[][]{{"ProjectYakuzaActive","true"},{"ProjectYakuzaStyle","dragon_of_dojima"},{"ProjectYakuzaWeaponProfile","bicycle"},{"Aim","false"},{"sneaking","false"},{"inTrees","false"},{"isTurningAround","false"},{"Weapon","2handed"},{"WalkSpeed","1"}})set.invoke(vars,row[0],row[1]);
  for(String injury:new String[]{"0","0.5","-0.5","1","-1"}){set.invoke(vars,"WalkInjury",injury);var chosen=(List<?>)select.invoke(movement,vars,new ArrayList<>());if(chosen.size()!=1||chosen.get(0)!=customNode)throw new AssertionError("bicycle movement lost to vanilla selector injury="+injury);}
  for(String[] row:new String[][]{{"ProjectYakuzaActive","false","true"},{"ProjectYakuzaStyle","none","dragon_of_dojima"},{"ProjectYakuzaWeaponProfile","crate","bicycle"},{"Aim","true","false"},{"sneaking","true","false"},{"inTrees","true","false"},{"isTurningAround","true","false"}}){set.invoke(vars,row[0],row[1]);if(((List<?>)select.invoke(movement,vars,new ArrayList<>())).contains(customNode))throw new AssertionError("bicycle walk fallback "+row[0]);set.invoke(vars,row[0],row[2]);}
  var doc=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(custom.toFile());var blends=doc.getElementsByTagName("m_2DBlends");if(blends.getLength()!=6)throw new AssertionError("native six-way speed/injury blend");for(int i=0;i<blends.getLength();i++)if(!((Element)blends.item(i)).getElementsByTagName("m_AnimName").item(0).getTextContent().startsWith("ProjectYakuza_DD_BicycleWalk"))throw new AssertionError("native unadapted carry blend");
  if(checked!=8)throw new AssertionError("five attack and three hold selectors "+checked);System.out.println("PASS eight native K2 attack/hold selectors, complete native movement-state competition for five injuries, six bicycle walk blends and seven fallback contracts; no game launch");
 }
}
